import React from 'react';
import { SolutionResponse } from '../../types';

interface ResultsDisplayProps {
    result: SolutionResponse;
}

export const ResultsDisplay: React.FC<ResultsDisplayProps> = ({ result }) => {
    // Функция для форматирования чисел (учитываем дробные)
    const formatNumber = (value: number): string => {
        if (Math.abs(value) < 0.000001 && value !== 0) {
            return value.toFixed(10).replace(/\.?0+$/, '');
        }
        return value.toFixed(8).replace(/\.?0+$/, '');
    };

    const formatError = (value: number): string => {
        if (value < 0.000001) {
            return value.toExponential(4);
        }
        return value.toFixed(8).replace(/\.?0+$/, '');
    };

    return (
        <div className="space-y-6 text-slate-900 font-sans">
            {/* Статус диагонального преобладания - без цветов */}
            <div className="p-4 border border-slate-900">
                <div className="flex items-center gap-2">
                    <span className="font-bold uppercase text-xs tracking-widest">
                        {result.diagonalDominance
                            ? '[ OK ] Диагональное преобладание выполнено'
                            : '[ ! ] Диагональное преобладание не выполнено'}
                    </span>
                </div>
            </div>

            {/* Основные характеристики - строгая сетка */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-0 border-t border-l">
                <div className="p-4 border-r border-b bg-white">
                    <div className="text-[10px] font-bold text-slate-400 uppercase mb-1">Определитель</div>
                    <div className="text-xl font-mono font-bold tracking-tighter">
                        {formatNumber(result.determinant)}
                    </div>
                </div>

                <div className="p-4 border-r border-b bg-white">
                    <div className="text-[10px] font-bold text-slate-400 uppercase mb-1">Норма матрицы</div>
                    <div className="text-xl font-mono font-bold tracking-tighter">
                        {formatNumber(result.matrixNorm)}
                    </div>
                </div>

                <div className="p-4 border-r border-b bg-white">
                    <div className="text-[10px] font-bold text-slate-400 uppercase mb-1">Итераций</div>
                    <div className="text-xl font-mono font-bold tracking-tighter">
                        {result.iterations}
                    </div>
                </div>
            </div>

            {/* Вектор решения */}
            <div className="border border-slate-200 p-4">
                <h3 className="text-xs font-bold uppercase text-slate-500 mb-4 tracking-widest">Вектор неизвестных x:</h3>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    {result.solution.map((value, index) => (
                        <div key={index} className="border-l-2 border-slate-900 pl-3 py-1">
                            <div className="text-[10px] text-slate-400 mb-1">x[{index + 1}]</div>
                            <div className="font-mono font-bold text-sm">
                                {formatNumber(value)}
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Вектор невязки */}
            <div className="border border-slate-200 p-4">
                <h3 className="text-xs font-bold uppercase text-slate-500 mb-4 tracking-widest">Вектор невязки:</h3>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    {result.residual.map((value, index) => (
                        <div key={index} className="border-l-2 border-slate-200 pl-3 py-1">
                            <div className="text-[10px] text-slate-400 mb-1">r[{index + 1}]</div>
                            <div className="font-mono text-sm text-slate-600">
                                {formatNumber(value)}
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Информация о сходимости */}
            <div className="border-t border-dashed pt-4">
                <p className="text-xs font-bold uppercase mb-1">
                    Результат: {result.message}
                </p>
                <p className="text-[10px] text-slate-500 font-mono">
                    MAX_ERROR: {' '}
                    {result.iterationHistory && result.iterationHistory.length > 0
                        ? formatError(result.iterationHistory[result.iterationHistory.length - 1].maxError)
                        : 'N/A'}
                </p>
            </div>
        </div>
    );
};
